update public.valuations set target_price = 180.59, intrinsic_base = 180.59, target_ebitda = 1986290000, target_revenues = 5329600000, shares_outstanding = 49636257, updated_at = now(), notes = $t$Recovery case built by segment: prices back to the higher of FY2023/24 realized, best observed costs, on FY2026-guided volumes; valued at a conservative 4.5x mid-cycle multiple. Met (Leer): 8.75M t x ($158.71 - $85.65) = $639.3M. High CV Thermal (PAMC): 32.25M t x ($77.74 - $36.00) = $1,346.1M. PRB $63.9M (FY2025), Core Marine Terminal $78.9M (FY2023), corporate -$141.9M (LTM). EBITDA $1,986.3M on $5,330M revenue (incl. $657M pass-through). Source: FiscalAI (NYSE_CNR; its FY2023/24 history is CONSOL's) and the Q2 FY2026 call. Hypotheses: Arch's FY2023/24 met and PRB data are not in FiscalAI, so the met price uses CONSOL's Itmann ($158.71, low-vol) for Leer (high-vol A), and PRB uses CNR's FY2025; the PAMC cost is derived from EBITDA per ton. Sensitivities: thermal cost $38.58 gives $173.04; met 8.5M t at $86 gives $178.65. Illustrative upside - not a target.$t$ where id = '98f39ff7-c0fe-4719-92db-8eba16f55056';
update public.valuation_lines set target_value = 5329600000, rationale = $t$Segment tons x price $4,672M plus $657M LTM freight and other pass-through (FiscalAI).$t$, updated_at = now() where id = 'ccfc2c0a-4102-4d99-8489-21005bd1026b';
update public.valuation_lines set target_value = 1986290000, rationale = $t$Met $639.3M + High CV Thermal $1,346.1M + PRB $63.9M + CMT $78.9M − corporate $141.9M.$t$, updated_at = now() where id = 'ea144264-e127-408b-8b66-a956d82a3c7a';
update public.valuation_lines set target_value = 37.3, rationale = $t$$1,986M / $5,330M; 42.5% on coal revenue alone. LTM 16.9%.$t$, updated_at = now() where id = 'b8f4464a-1fdb-4794-8388-d0320d27959c';
