update public.valuations set updated_at = now(), notes = replace(notes, $t$The Recovery case ($162.02) reaches $1,780M of EBITDA by applying CNR's own 3Y-high margin (41.7%, set by pre-merger CONSOL) to today's revenue;$t$, $t$The Recovery case ($180.59) builds $1,986M of EBITDA by segment at FY2023 prices;$t$) where id = '0d934cca-282b-4448-830a-5a6fd902afd1';
update public.valuation_lines set rationale = $t$$2,060M / $5,326M = 38.7%, vs 37.3% in the segment-built Recovery case.$t$ where id = '8488b8b9-bc82-4d58-afb8-10c698a3e79f';
update public.own_thesis set bullet_3 = $t$Valuation builds on the two pillars above: by segment at FY2023 prices, met $639M (8.75M t at $73/t) plus thermal $1,346M (32.25M t at $41.74/t) give $1,986M EBITDA; with net cash held, 4.5x gives $180.59, +98% vs $91.36.$t$, claim_3 = $t$EBITDA rises from $723M LTM (with $125M of insurance) toward $1,986M as the PAMC thermal margin returns toward ~$42/t and Leer met toward ~$73/t on 8.75M t.$t$ where id = 'bca79e2f-a68a-45a1-a61d-d850b18fb5ef';
update public.thesis_summaries set headline = $t$4.5x segment EBITDA of $1,986M gives $180.59$t$, bullets = array[$t$Met 8.75M t at $73/t: $639M; thermal 32.25M t at $41.74/t: $1,346M.$t$, $t$The met price is a hypothesis: Arch 2023/24 prices are not in FiscalAI.$t$, $t$+98% vs $91.36; Bear case $57.05.$t$], updated_at = now() where member_ticker = 'CNR' and slot = 3 and position_id = (select position_id from public.own_thesis where id = 'bca79e2f-a68a-45a1-a61d-d850b18fb5ef');
update public.scorecard_ratings set christian = 3, updated_at = now(), reason = $t$Price $91.36 vs Recovery 2030 IVO $180.59: 49% discount. Not 4: the met price behind the IVO is a hypothesis, and the Bear case ($57.05) sits below the price.$t$ where id = '79b91dca-c643-442a-b18b-2fe13245512d';
